const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');
const assert = require('node:assert/strict');
const root = path.resolve(__dirname, '../..');
const read = p => fs.readFileSync(path.join(root,p));
const build = read('dashboard/build-dashboard.ps1').toString();
const names = [...build.match(/\$Files\s*=\s*@\(([\s\S]*?)\)/)[1].matchAll(/"([^"]+)"/g)].map(m=>m[1]);
const prefix = read('shared/provider-registry-core.js');
const expected = Buffer.concat([prefix,...names.map(n=>read('dashboard/src/'+n))]);
const actual = read('dashboard/dashboard.js');
assert.ok(actual.equals(expected),'shipped bundle must include shared registry before all dashboard chunks');
const source = actual.toString();
const registryStart = source.indexOf('function getStreamShellProviderRegistry()');
const registryEnd = source.indexOf('function renderProviderSelector()',registryStart);
const ctx = vm.createContext({URL,settingsValues:{}});
vm.runInContext(source.slice(0,prefix.length)+source.slice(registryStart,registryEnd),ctx);
assert.equal(vm.runInContext('streamShellPinnedProviders(getStreamShellProviderRegistry()).length',ctx),5);
assert.equal(vm.runInContext('getStreamShellProviderRegistry().providers.some(p=>p.id === "youtube-music")',ctx),true);
console.log('Shipped dashboard bundle order and registry startup: PASS');
